CREATE TRIGGER search_listing_update AFTER UPDATE ON public.listings FOR EACH ROW WHEN (old.title IS DISTINCT FROM new.title OR old.description IS DISTINCT FROM new.description OR old.compatibility_notes IS DISTINCT FROM new.compatibility_notes OR old.part_number IS DISTINCT FROM new.part_number OR old.category IS DISTINCT FROM new.category OR old.subcategory IS DISTINCT FROM new.subcategory OR old.brand IS DISTINCT FROM new.brand OR old.condition IS DISTINCT FROM new.condition OR old.status IS DISTINCT FROM new.status OR old.price_cents IS DISTINCT FROM new.price_cents OR old.created_at IS DISTINCT FROM new.created_at OR old.source_car_id IS DISTINCT FROM new.source_car_id OR old.seller_id IS DISTINCT FROM new.seller_id) EXECUTE FUNCTION public.queue_search_change('listing', 'id');
